<script lang="ts">
 import {page} from '$app/state';import {goto} from '$app/navigation';import {app,run} from '../../lib/app.svelte';import {claimStore} from '../../lib/store';import SignIn from '../../lib/screens/SignIn.svelte';import Dashboard from '../../lib/screens/Dashboard.svelte';import ClaimList from '../../lib/screens/ClaimList.svelte';import ClaimDetail from '../../lib/screens/ClaimDetail.svelte';import Batches from '../../lib/screens/Batches.svelte';import Policy from '../../lib/screens/Policy.svelte';import Utility from '../../lib/screens/Utility.svelte';
 const path=$derived(page.url.pathname);const id=$derived(path.startsWith('/claims/')?path.split('/')[2]:'');const claim=$derived(app.data?.claims.find(c=>c.id===id));let creating=false;
 $effect(()=>{if(!app.ready)return;if(path==='/claims/new'&&!creating){creating=true;run(()=>claimStore.create()).then(c=>{creating=false;if(c)goto('/claims/'+c.id,{replaceState:true});});}else if(id&&id!=='new'&&!claim)goto('/signin?reason=forbidden',{replaceState:true});});
</script>
{#if app.ready}{#if path==='/signin'}<SignIn/>{:else if path==='/dashboard'}<Dashboard/>{:else if path==='/claims'}<ClaimList mode="employee"/>{:else if path==='/manager'}<ClaimList mode="manager"/>{:else if path==='/finance'}<ClaimList mode="finance"/>{:else if claim}{#key claim.id}<ClaimDetail initial={claim}/>{/key}{:else if path==='/batches'}<Batches/>{:else if path==='/policy'}<Policy/>{:else if ['/settings','/privacy','/about','/notifications'].includes(path)}<Utility screen={path}/>{/if}{/if}